using Azure.Identity;
using Azure.AI.OpenAI;
using OpenAI.Chat;

public class EnterpriseAzureOpenAiService
{
    private readonly ChatClient _chatClient;

    public EnterpriseAzureOpenAiService(IConfiguration configuration)
    {
        var endpoint = configuration["AzureOpenAI:Endpoint"]; // https://corp-ai-prod.openai.azure.com/
        var deploymentName = configuration["AzureOpenAI:DeploymentName"] ?? "gpt-4o";

        // Authenticate using DefaultAzureCredential (Managed Identity in Azure, Azure CLI locally)
        var azureClient = new AzureOpenAIClient(
            new Uri(endpoint!),
            new DefaultAzureCredential());

        // Get standard ChatClient scoped to the deployment
        _chatClient = azureClient.GetChatClient(deploymentName);
    }

    public async Task<string> AskQuestionAsync(string prompt, CancellationToken ct = default)
    {
        var messages = new ChatMessage[]
        {
            new SystemChatMessage("You are a corporate enterprise assistant."),
            new UserChatMessage(prompt)
        };

        var response = await _chatClient.CompleteChatAsync(messages, cancellationToken: ct);
        return response.Value.Content[0].Text;
    }
}
